import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        if (n <= 0) {
            System.out.println();
            return;
        }
        String[] parts = br.readLine().trim().split("\\s+");
        Node head = null, tail = null;
        for (int i = 0; i < n; i++) {
            int val = Integer.parseInt(parts[i]);
            Node newNode = new Node(val);
            if (head == null) head = newNode;
            else tail.next = newNode;
            tail = newNode;
        }
        head = bucketSort(head);
        StringBuilder sb = new StringBuilder();
        Node curr = head;
        while (curr != null) {
            sb.append(curr.data).append(' ');
            curr = curr.next;
        }
        System.out.println(sb.toString().trim());
    }

    static Node bucketSort(Node head) {
        Node minMax = findMinMax(head);
        int minVal = minMax.data;
        int maxVal = minMax.data;
        for (Node curr = head; curr != null; curr = curr.next) {
            if (curr.data < minVal) minVal = curr.data;
            if (curr.data > maxVal) maxVal = curr.data;
        }
        int range = maxVal - minVal;
        int bucketCount = Math.max(1, (int) Math.sqrt(n(head)));
        Node[] buckets = new Node[bucketCount];
        Node[] tails = new Node[bucketCount];
        Node curr = head;
        while (curr != null) {
            Node next = curr.next;
            curr.next = null;
            int bucketIdx = bucketIndex(curr.data, minVal, maxVal, bucketCount);
            if (buckets[bucketIdx] == null) {
                buckets[bucketIdx] = curr;
            } else {
                tails[bucketIdx].next = curr;
            }
            tails[bucketIdx] = curr;
            curr = next;
        }
        Node result = null, resTail = null;
        for (int i = 0; i < bucketCount; i++) {
            if (buckets[i] != null) {
                if (result == null) result = buckets[i];
                else resTail.next = buckets[i];
                resTail = tails[i];
            }
        }
        for (int i = 0; i < bucketCount; i++) {
            if (buckets[i] != null) {
                buckets[i] = insertionSort(buckets[i]);
            }
        }
        result = null;
        resTail = null;
        for (int i = 0; i < bucketCount; i++) {
            if (buckets[i] != null) {
                if (result == null) result = buckets[i];
                else resTail.next = buckets[i];
                while (resTail.next != null) resTail = resTail.next;
            }
        }
        return result;
    }

    static int n(Node head) {
        int cnt = 0;
        while (head != null) { cnt++; head = head.next; }
        return cnt;
    }

    static Node findMinMax(Node head) {
        Node minNode = head, maxNode = head;
        Node curr = head;
        while (curr != null) {
            if (curr.data < minNode.data) minNode = curr;
            if (curr.data > maxNode.data) maxNode = curr;
            curr = curr.next;
        }
        return minNode == maxNode ? minNode : minNode;
    }

    static int bucketIndex(int val, int minVal, int maxVal, int bucketCount) {
        if (minVal == maxVal) return 0;
        return (val - minVal) * (bucketCount - 1) / (maxVal - minVal);
    }

    static Node insertionSort(Node head) {
        Node sorted = null;
        while (head != null) {
            Node next = head.next;
            if (sorted == null || head.data <= sorted.data) {
                head.next = sorted;
                sorted = head;
            } else {
                Node prev = sorted;
                while (prev.next != null && prev.next.data < head.data) {
                    prev = prev.next;
                }
                head.next = prev.next;
                prev.next = head;
            }
            head = next;
        }
        return sorted;
    }
}
